import hashlib,struct,zlib
d=open('records.bin','rb').read()
r=d[:15]; tb=r[-4:]
M=0xffffffff
def fnv1a(s,h=0x811c9dc5):
    for b in s: h=((h^b)*0x01000193)&M
    return h
def fnv1(s,h=0x811c9dc5):
    for b in s: h=((h*0x01000193)&M)^b
    return h
def djb2(s,h=5381):
    for b in s: h=(h*33+b)&M
    return h
def djb2x(s,h=5381):
    for b in s: h=(h*33^b)&M
    return h
def sdbm(s,h=0):
    for b in s: h=(b+(h<<6)+(h<<16)-h)&M
    return h
def jen(s):
    h=0
    for b in s:
        h=(h+b)&M;h=(h+(h<<10))&M;h^=h>>6
    h=(h+(h<<3))&M;h^=h>>11;h=(h+(h<<15))&M
    return h
def lose(s):
    h=0
    for b in s: h=(h+b)&M
    return h
def mm3(data,seed=0):
    c1,c2=0xcc9e2d51,0x1b873593
    h=seed;n=len(data)//4
    rotl=lambda x,r:((x<<r)|(x>>(32-r)))&M
    for i in range(n):
        k=struct.unpack_from('<I',data,i*4)[0]
        k=(k*c1)&M;k=rotl(k,15);k=(k*c2)&M
        h^=k;h=rotl(h,13);h=(h*5+0xe6546b64)&M
    t=data[n*4:];k=0
    for i in range(len(t)-1,-1,-1): k=(k<<8)|t[i]
    if t:
        k=(k*c1)&M;k=rotl(k,15);k=(k*c2)&M;h^=k
    h^=len(data);h^=h>>16;h=(h*0x85ebca6b)&M;h^=h>>13;h=(h*0xc2b2ae35)&M;h^=h>>16
    return h
tg={struct.unpack('>I',tb)[0],struct.unpack('<I',tb)[0]}
fs=[fnv1a,fnv1,djb2,djb2x,sdbm,jen,mm3,lambda s:zlib.crc32(s)]
for s in range(0,6):
  for e in range(4,12):
    seg=r[s:e]
    for f in fs:
